SELECT id, customer_id, account_type, balance, opened_date, status, AVG(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS balance_avg_3, PERCENT_RANK() OVER (PARTITION BY status ORDER BY balance DESC NULLS FIRST) AS balance_percent_rank, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY balance DESC NULLS FIRST) AS balance_cume_dist, SUM(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM accounts;
